type Toast = (message: string, success?: boolean) => void;

const asText = (value: unknown, fallback = "") =>
  value === undefined || value === null || String(value).trim() === "" ? fallback : String(value);
const asNumber = (value: unknown, fallback = 0) => {
  const parsed = typeof value === "number" ? value : Number(String(value ?? "").replace(",", "."));
  return Number.isFinite(parsed) ? parsed : fallback;
};
const asList = (value: unknown, keys: string[] = []) => {
  if (Array.isArray(value)) return value.filter((item): item is JsonRecord => Boolean(item) && typeof item === "object");
  if (!value || typeof value !== "object") return [];
  const record = value as JsonRecord;
  for (const key of keys) {
    if (Array.isArray(record[key])) return record[key].filter((item): item is JsonRecord => Boolean(item) && typeof item === "object");
  }
  return [];
};
const asDate = (value: unknown) => {
  if (!value) return "—";
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? asText(value) : date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
};
const idOf = (record: JsonRecord) => asText(record.id || record.serverId || record.groupId || record.provider, "");
const titleOf = (record: JsonRecord, fallback = "Registro") => asText(record.name || record.title || record.groupName || record.email, fallback);
const recordTitle = (record: JsonRecord, fallback = "Registro") => titleOf(record, fallback);
const initials = (value: unknown) => asText(value, "?").trim().split(/\s+/).slice(0, 2).map((part) => part.slice(0, 1).toUpperCase()).join("") || "?";
const text = (value: unknown, fallback = "—") => asText(value, fallback);
const errText = (error: unknown) => error instanceof Error ? error.message : "Não foi possível concluir a operação.";
const bool = (value: unknown, fallback = false) => value === true || value === 1 || value === "1" || value === "true" ? true : value === false || value === 0 || value === "0" || value === "false" ? false : fallback;

const navigateAdmin = (section: string) => {
  const url = new URL(window.location.href);
  url.searchParams.set("section", section);
  window.history.pushState({}, "", url.toString());
  window.dispatchEvent(new PopStateEvent("popstate"));
};

function AdvancedLoading({ label }: { label: string }) {
  return <div className="admin-loading"><Activity size={21} className="admin-spin" />{label}</div>;
}

export function AdvancedEmpty({ icon: Icon = AlertTriangle, title, message, action }: { icon?: typeof AlertTriangle; title: string; message: string; action?: ReactNode }) {
  return <div className="admin-empty"><Icon size={29} /><strong>{title}</strong><span>{message}</span>{action}</div>;
}

function AdvancedConfirm({ title, message, onCancel, onConfirm, danger = true }: { title: string; message: string; onCancel: () => void; onConfirm: () => void; danger?: boolean }) {
  return <AdminModal title={title} subtitle="Confirme esta ação para continuar." onClose={onCancel} footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onCancel}>Cancelar</button><button type="button" className={`admin-button ${danger ? "admin-button--danger" : "admin-button--primary"}`} onClick={onConfirm}>Confirmar</button></>}><div className="admin-confirm"><AlertTriangle size={28} /><p>{message}</p></div></AdminModal>;
}

export function AdminDashboardWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [data, setData] = useState<{ servers: JsonRecord[]; users: JsonRecord[]; support: JsonRecord[]; sales: JsonRecord[] }>({ servers: [], users: [], support: [], sales: [] });
  const [loading, setLoading] = useState(true);
  const load = useCallback(async () => {
    setLoading(true);
    try {
      const response = await adminApi.dashboard();
      setData({ servers: asList(response.servers, ["servers"]), users: asList(response.users, ["users"]), support: asList(response.support, ["threads"]), sales: asList(response.sales, ["events", "sales"]) });
    } catch (error) { onToast(errText(error), false); }
    finally { setLoading(false); }
  }, [onToast]);
  useEffect(() => { void load(); }, [load]);
  const activeServers = data.servers.filter((item) => bool(item.isActive, true)).length;
  const activeUsers = data.users.filter((item) => bool(item.isActive, true)).length;
  const openSupport = data.support.filter((item) => asText(item.status || (item.thread as JsonRecord | undefined)?.status, "open") === "open").length;
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} />{loading ? <AdvancedLoading label="Carregando visão geral…" /> : <>
    <div className="admin-metric-grid"><button type="button" className="admin-metric-card" onClick={() => navigateAdmin("users")}><span>Usuários</span><strong>{data.users.length}</strong><small>{activeUsers} contas ativas</small></button><button type="button" className="admin-metric-card" onClick={() => navigateAdmin("servers")}><span>Servidores</span><strong>{data.servers.length}</strong><small>{activeServers} ativos</small></button><button type="button" className="admin-metric-card" onClick={() => navigateAdmin("support")}><span>Atendimentos</span><strong>{data.support.length}</strong><small>{openSupport} em aberto</small></button><button type="button" className="admin-metric-card" onClick={() => navigateAdmin("payments")}><span>Vendas recentes</span><strong>{data.sales.length}</strong><small>Acessar pagamentos</small></button></div>
    <div className="admin-two-column"><section className="admin-subpanel"><header><div><h2>Servidores cadastrados</h2><p>Infraestrutura usada pelas instâncias.</p></div><Server size={20} /></header>{data.servers.length === 0 ? <AdvancedEmpty icon={Server} title="Nenhum servidor configurado" message="Cadastre um host para liberar novas instâncias." action={<button type="button" className="admin-button admin-button--primary" onClick={() => navigateAdmin("servers")}><Plus size={16} />Cadastrar servidor</button>} /> : <div className="admin-mini-list">{data.servers.slice(0, 8).map((item) => <div className="admin-mini-row" key={idOf(item)}><span className="admin-avatar"><Server size={17} /></span><div><strong>{titleOf(item)}</strong><small>{asText(item.baseUrl)} · limite {asNumber(item.sessionLimit) === 0 ? "ilimitado" : `${asNumber(item.sessionLimit)} inst.`}</small></div><AdminStatusPill value={bool(item.isActive, true) ? "Ativo" : "Inativo"} /></div>)}</div>}</section><section className="admin-subpanel"><header><div><h2>Usuários recentes</h2><p>Contas mais novas do painel.</p></div><Users size={20} /></header>{data.users.length === 0 ? <AdvancedEmpty icon={Users} title="Nenhum usuário cadastrado" message="As novas contas aparecerão aqui." /> : <div className="admin-mini-list">{data.users.slice(0, 6).map((item) => <div className="admin-mini-row" key={idOf(item)}><span className="admin-avatar">{titleOf(item, "U").slice(0, 1).toUpperCase()}</span><div><strong>{titleOf(item)}</strong><small>{asText(item.email, "Sem e-mail")} · {asDate(item.createdAt)}</small></div><AdminStatusPill value={bool(item.isActive, true) ? "Ativo" : "Inativo"} /></div>)}</div>}</section></div>
  </>}</div>;
}

type ServerDraft = { name: string; baseUrl: string; apiType: string; globalApiKey: string; sessionLimit: string; isActive: boolean };
const serverDraft = (item?: JsonRecord | null): ServerDraft => ({ name: asText(item?.name), baseUrl: asText(item?.baseUrl), apiType: asText(item?.apiType, "wuzapi"), globalApiKey: "", sessionLimit: String(asNumber(item?.sessionLimit)), isActive: bool(item?.isActive, true) });

function ServerEditor({ item, onClose, onSaved, onToast }: { item?: JsonRecord | null; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [form, setForm] = useState(() => serverDraft(item)); const [saving, setSaving] = useState(false); const change = <K extends keyof ServerDraft>(key: K, value: ServerDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (form.name.trim().length < 2 || !/^https?:\/\//i.test(form.baseUrl.trim())) { onToast("Informe nome e URL base válidos (http/https).", false); return; } const limit = Number.parseInt(form.sessionLimit, 10); if (!Number.isInteger(limit) || limit < 0) { onToast("O limite de sessões deve ser zero ou maior.", false); return; } setSaving(true); try { const payload: JsonRecord = { name: form.name.trim(), baseUrl: form.baseUrl.trim(), apiType: form.apiType, sessionLimit: limit, isActive: form.isActive, ...(!item || form.globalApiKey.trim() ? { globalApiKey: form.globalApiKey.trim() } : {}) }; await adminApi.botServer(item ? idOf(item) : "", payload, item ? "PUT" : "POST"); onToast(item ? "Servidor atualizado." : "Servidor cadastrado.", true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <AdminModal title={item ? "Editar servidor" : "Novo servidor"} subtitle="Hosts WuzAPI e limites de sessões do BotAdmin." onClose={onClose} footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="server-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar servidor"}</button></>}><form id="server-form" className="admin-form admin-form--grid" onSubmit={submit}><label>Nome<input value={form.name} onChange={(event) => change("name", event.currentTarget.value)} autoFocus required /></label><label>URL base<input type="url" value={form.baseUrl} onChange={(event) => change("baseUrl", event.currentTarget.value)} placeholder="https://wuzapi.exemplo.com" required /></label><label>Tipo de API<select value={form.apiType} onChange={(event) => change("apiType", event.currentTarget.value)}><option value="wuzapi">WuzAPI</option><option value="evolution">Evolution API</option><option value="custom">Personalizada</option></select></label><label>Chave global (opcional)<input type="password" value={form.globalApiKey} onChange={(event) => change("globalApiKey", event.currentTarget.value)} autoComplete="new-password" /></label><label>Limite de sessões<input type="number" min="0" value={form.sessionLimit} onChange={(event) => change("sessionLimit", event.currentTarget.value)} /><small>Use 0 para ilimitado.</small></label><label className="admin-toggle-row"><span>Servidor ativo</span><button type="button" className={`admin-switch ${form.isActive ? "is-on" : ""}`} aria-pressed={form.isActive} onClick={() => change("isActive", !form.isActive)}><i /></button></label></form></AdminModal>;
}

function ServerAssignmentEditor({ server, onClose, onSaved, onToast }: { server: JsonRecord; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [instances, setInstances] = useState<JsonRecord[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async (search = "") => {
    setLoading(true);
    try {
      const response = await adminApi.botServerInstances({ q: search.trim() || undefined, limit: 100 });
      const list = asList(response, ["instances", "items"]);
      setInstances(list);
      if (!search.trim()) {
        setSelected(new Set(list.filter((item) => String(item.serverId || item.server_id || "") === idOf(server)).map(idOf)));
      }
    } catch (error) {
      onToast(errText(error), false);
      setInstances([]);
    } finally {
      setLoading(false);
    }
  }, [onToast, server]);

  useEffect(() => {
    const timer = window.setTimeout(() => void load(query), 180);
    return () => window.clearTimeout(timer);
  }, [load, query]);

  const save = async () => {
    if (selected.size === 0) {
      onToast("Selecione ao menos uma instância para vincular.", false);
      return;
    }
    setSaving(true);
    try {
      await adminApi.assignBotServerInstances(idOf(server), Array.from(selected));
      onToast("Instâncias vinculadas ao servidor.", true);
      onSaved();
      onClose();
    } catch (error) {
      onToast(errText(error), false);
    } finally {
      setSaving(false);
    }
  };

  return <AdminModal title={`Instâncias de ${titleOf(server)}`} subtitle="Selecione os perfis que usarão este host. Instâncias selecionadas serão movidas para o servidor." onClose={onClose} wide footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="button" className="admin-button admin-button--primary" onClick={() => void save()} disabled={saving || loading}>{saving ? "Salvando…" : "Salvar vínculos"}</button></>}><div className="admin-assignment-toolbar"><AdminSearchBar value={query} onChange={setQuery} placeholder="Pesquisar por nome, telefone ou e-mail" /><span>{selected.size} selecionada(s)</span></div><div className="admin-assignment-list">{loading ? <AdvancedLoading label="Carregando instâncias…" /> : instances.length === 0 ? <AdvancedEmpty icon={Server} title="Nenhuma instância disponível" message="Crie ou atualize um perfil antes de vinculá-lo ao host." /> : instances.map((instance, index) => { const id = idOf(instance) || String(index); const assignedTo = asText(instance.serverId || instance.server_id, ""); return <label className="admin-assignment-row" key={id}><input type="checkbox" checked={selected.has(id)} onChange={(event) => setSelected((current) => { const next = new Set(current); if (event.currentTarget.checked) next.add(id); else next.delete(id); return next; })} /><span className="admin-avatar">{initials(recordTitle(instance, "P"))}</span><span><strong>{recordTitle(instance, `Perfil #${id}`)}</strong><small>{text(instance.phone || instance.whatsappNumber, "Número não informado")} · {text(instance.sessionStatus || instance.status, "Desconectado")}</small></span>{assignedTo && assignedTo !== idOf(server) ? <em>Outro servidor</em> : null}</label>; })}</div></AdminModal>;
}

export function AdminServersWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [servers, setServers] = useState<JsonRecord[]>([]); const [loading, setLoading] = useState(true); const [editor, setEditor] = useState<JsonRecord | null | undefined>(undefined); const [assignment, setAssignment] = useState<JsonRecord | null>(null); const [remove, setRemove] = useState<JsonRecord | null>(null);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.botServers(); setServers(asList(response, ["servers"])); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  const deleteServer = async () => { if (!remove) return; try { await adminApi.botServer(idOf(remove), undefined, "DELETE"); onToast("Servidor removido.", true); setRemove(null); void load(); } catch (error) { onToast(errText(error), false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<button type="button" className="admin-button admin-button--primary" onClick={() => setEditor(null)}><Plus size={17} />Novo servidor</button>} />{loading ? <AdvancedLoading label="Carregando servidores…" /> : servers.length === 0 ? <AdvancedEmpty icon={Server} title="Nenhum servidor cadastrado" message="Cadastre o primeiro host para permitir conexões." action={<button type="button" className="admin-button admin-button--primary" onClick={() => setEditor(null)}><Plus size={16} />Cadastrar servidor</button>} /> : <div className="admin-record-list">{servers.map((server) => <AdminRecordCard key={idOf(server)} record={{ ...server, title: titleOf(server, `Servidor #${idOf(server)}`), email: server.baseUrl, status: bool(server.isActive, true) ? "Ativo" : "Inativo" }} extra={<small>{asText(server.apiType, "wuzapi")} · limite {asNumber(server.sessionLimit) === 0 ? "ilimitado" : `${asNumber(server.sessionLimit)} sessões`} · criado {asDate(server.createdAt)}</small>} actions={<details className="admin-more"><summary aria-label="Ações do servidor"><MoreVertical size={17} /></summary><div className="admin-more__menu"><button type="button" onClick={() => setEditor(server)}><Pencil size={15} />Editar</button><button type="button" onClick={() => setAssignment(server)}><Settings size={15} />Instâncias vinculadas</button><button type="button" className="is-danger" onClick={() => setRemove(server)}><Trash2 size={15} />Excluir</button></div></details>} />)}</div>}{editor !== undefined ? <ServerEditor item={editor} onClose={() => setEditor(undefined)} onSaved={() => void load()} onToast={onToast} /> : null}{assignment ? <ServerAssignmentEditor server={assignment} onClose={() => setAssignment(null)} onSaved={() => void load()} onToast={onToast} /> : null}{remove ? <AdvancedConfirm title="Excluir servidor?" message={`O host ${titleOf(remove)} será removido. As instâncias vinculadas precisarão ser migradas.`} onCancel={() => setRemove(null)} onConfirm={() => void deleteServer()} /> : null}</div>;
}

type MegaDraft = { email: string; password: string; clearPassword: boolean; externalAccountsEnabled: boolean; externalAccountsUrl: string; resetSession: boolean };
function AdminMegaEditor({ initial, onClose, onSaved, onToast }: { initial: JsonRecord; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [form, setForm] = useState<MegaDraft>({ email: asText(initial.email), password: "", clearPassword: false, externalAccountsEnabled: bool(initial.externalAccountsEnabled), externalAccountsUrl: asText(initial.externalAccountsUrl), resetSession: false }); const [saving, setSaving] = useState(false); const change = <K extends keyof MegaDraft>(key: K, value: MegaDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (form.clearPassword && form.password.trim()) { onToast("Escolha entre limpar ou informar uma nova senha.", false); return; } setSaving(true); try { const payload: JsonRecord = { email: form.email.trim() || null, externalAccountsEnabled: form.externalAccountsEnabled, externalAccountsUrl: form.externalAccountsUrl.trim() || null, ...(form.password.trim() && !form.clearPassword ? { password: form.password.trim() } : {}), ...(form.clearPassword ? { clearPassword: true } : {}), ...(form.resetSession ? { resetSession: true } : {}) }; await adminApi.mega(payload); onToast("Credenciais do Mega atualizadas.", true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <AdminModal title="Credenciais do Mega downloader" subtitle="A sessão é usada pelo autodownloader para arquivos compartilhados." onClose={onClose} footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="mega-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar credenciais"}</button></>}><form id="mega-form" className="admin-form admin-form--grid" onSubmit={submit}><label>E-mail do Mega<input type="email" value={form.email} onChange={(event) => change("email", event.currentTarget.value)} autoFocus /></label><label>Nova senha <small>(vazio mantém a atual)</small><input type="password" value={form.password} onChange={(event) => change("password", event.currentTarget.value)} autoComplete="new-password" /></label><label className="admin-toggle-row"><span>Limpar senha salva</span><button type="button" className={`admin-switch ${form.clearPassword ? "is-on" : ""}`} aria-pressed={form.clearPassword} onClick={() => change("clearPassword", !form.clearPassword)}><i /></button></label><label className="admin-toggle-row"><span>Contas externas habilitadas</span><button type="button" className={`admin-switch ${form.externalAccountsEnabled ? "is-on" : ""}`} aria-pressed={form.externalAccountsEnabled} onClick={() => change("externalAccountsEnabled", !form.externalAccountsEnabled)}><i /></button></label><label className="admin-form__full">Endpoint externo opcional<input type="url" value={form.externalAccountsUrl} onChange={(event) => change("externalAccountsUrl", event.currentTarget.value)} placeholder="https://…" /></label><label className="admin-toggle-row admin-form__full"><span>Renovar sessão no próximo acesso</span><button type="button" className={`admin-switch ${form.resetSession ? "is-on" : ""}`} aria-pressed={form.resetSession} onClick={() => change("resetSession", !form.resetSession)}><i /></button></label></form></AdminModal>;
}

export function AdminMegaWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [data, setData] = useState<JsonRecord>({}); const [loading, setLoading] = useState(true); const [editor, setEditor] = useState(false);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.mega(); setData((response.credentials || response) as JsonRecord); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<button type="button" className="admin-button admin-button--primary" onClick={() => setEditor(true)}><Pencil size={16} />Configurar</button>} />{loading ? <AdvancedLoading label="Carregando credenciais…" /> : <section className="admin-info-card admin-info-card--wide"><div className="admin-info-card__head"><span className="admin-avatar"><CloudDownload size={18} /></span><div><strong>Mega.NZ</strong><span>Downloader administrativo</span></div><AdminStatusPill value={data.hasPassword ? "Configurado" : "Pendente"} /></div><dl><div><dt>E-mail</dt><dd>{asText(data.email, "Não configurado")}</dd></div><div><dt>Sessão</dt><dd>{data.hasSession ? `Ativa${data.sessionEmail ? ` (${data.sessionEmail})` : ""}` : "Não configurada"}</dd></div><div><dt>Atualizado</dt><dd>{asDate(data.updatedAt)}</dd></div></dl><p>As credenciais permanecem protegidas e só são utilizadas no servidor para resolver mídias autorizadas.</p></section>}{editor ? <AdminMegaEditor initial={data} onClose={() => setEditor(false)} onSaved={() => void load()} onToast={onToast} /> : null}</div>;
}

type GroupDraft = { name: string; description: string; inviteLink: string; transferUserId: string; transferInstanceId: string; active: boolean; adminsOnly: boolean; locked: boolean; planRenewalAdminsOnly: boolean; planRenewalSilent: boolean; allowPlay: boolean; allowBan: boolean; allowLinks: boolean; aiProvider: string; aiModel: string; aiPrompt: string; welcomeText: string };
const groupDraft = (item?: JsonRecord | null): GroupDraft => {
  const settings = (item?.settings && typeof item.settings === "object" ? item.settings : {}) as JsonRecord;
  const welcome = (settings.welcomeConfig && typeof settings.welcomeConfig === "object" ? settings.welcomeConfig : {}) as JsonRecord;
  const toggles = (settings.commandToggles && typeof settings.commandToggles === "object" ? settings.commandToggles : {}) as JsonRecord;
  return { name: asText(item?.name || item?.groupName), description: asText(item?.description), inviteLink: asText(item?.inviteLink), transferUserId: "", transferInstanceId: "", active: bool(item?.active ?? item?.isActive, true), adminsOnly: bool(item?.adminsOnly), locked: bool(item?.locked), planRenewalAdminsOnly: bool(settings.planRenewalAdminsOnly), planRenewalSilent: bool(settings.planRenewalSilent), allowPlay: bool(toggles.play, true), allowBan: bool(toggles.ban, true), allowLinks: bool(toggles.antilinks, true), aiProvider: asText(settings.aiProvider, "groq"), aiModel: asText(settings.aiModel, "qwen2.5:7b"), aiPrompt: asText(settings.aiPrompt), welcomeText: asText(welcome.message || welcome.text) };
};

function GroupEditor({ item, onClose, onSaved, onToast }: { item: JsonRecord; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [form, setForm] = useState(() => groupDraft(item)); const [saving, setSaving] = useState(false); const change = <K extends keyof GroupDraft>(key: K, value: GroupDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (form.name.trim().length < 2) { onToast("Informe um nome válido para o grupo.", false); return; } if (form.transferUserId && !/^\d+$/.test(form.transferUserId.trim())) { onToast("ID do usuário de destino inválido.", false); return; } if (form.transferInstanceId && !/^\d+$/.test(form.transferInstanceId.trim())) { onToast("ID da instância de destino inválido.", false); return; } setSaving(true); try { const payload: JsonRecord = { name: form.name.trim(), description: form.description.trim() || null, ...(form.inviteLink.trim() ? { inviteLink: form.inviteLink.trim() } : {}), ...(form.transferUserId.trim() ? { transferToUserId: Number(form.transferUserId), ...(form.transferInstanceId.trim() ? { targetInstanceId: Number(form.transferInstanceId) } : {}) } : {}), active: form.active, adminsOnly: form.adminsOnly, locked: form.locked, planRenewalAdminsOnly: form.planRenewalAdminsOnly, planRenewalSilent: form.planRenewalSilent, commandToggles: { play: form.allowPlay, ban: form.allowBan, antilinks: form.allowLinks }, aiProvider: form.aiProvider, aiModel: form.aiModel.trim(), aiPrompt: form.aiPrompt, welcomeConfig: form.welcomeText.trim() ? { message: form.welcomeText.trim() } : null }; await adminApi.group(idOf(item), payload, "PATCH"); onToast("Configurações do grupo atualizadas.", true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <AdminModal title={`Gerenciar ${asText(item.name || item.groupName, "grupo")}`} subtitle="Ativação, permissões, comandos, boas-vindas e inteligência do grupo." onClose={onClose} wide footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="group-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar alterações"}</button></>}><form id="group-form" className="admin-form admin-form--grid" onSubmit={submit}><label>Nome do grupo<input value={form.name} onChange={(event) => change("name", event.currentTarget.value)} autoFocus required /></label><label>Link de convite<input value={form.inviteLink} onChange={(event) => change("inviteLink", event.currentTarget.value)} placeholder="https://chat.whatsapp.com/…" /></label><label className="admin-form__full">Descrição<textarea rows={3} value={form.description} onChange={(event) => change("description", event.currentTarget.value)} /></label><fieldset className="admin-form__full admin-permissions"><legend>Permissões do grupo</legend><label className="admin-toggle-row"><span>Grupo ativo</span><button type="button" className={`admin-switch ${form.active ? "is-on" : ""}`} aria-pressed={form.active} onClick={() => change("active", !form.active)}><i /></button></label><label className="admin-toggle-row"><span>Somente administradores podem enviar</span><button type="button" className={`admin-switch ${form.adminsOnly ? "is-on" : ""}`} aria-pressed={form.adminsOnly} onClick={() => change("adminsOnly", !form.adminsOnly)}><i /></button></label><label className="admin-toggle-row"><span>Bloquear edição de dados</span><button type="button" className={`admin-switch ${form.locked ? "is-on" : ""}`} aria-pressed={form.locked} onClick={() => change("locked", !form.locked)}><i /></button></label><label className="admin-toggle-row"><span>Somente admins renovam planos</span><button type="button" className={`admin-switch ${form.planRenewalAdminsOnly ? "is-on" : ""}`} aria-pressed={form.planRenewalAdminsOnly} onClick={() => change("planRenewalAdminsOnly", !form.planRenewalAdminsOnly)}><i /></button></label><label className="admin-toggle-row"><span>Renovação silenciosa</span><button type="button" className={`admin-switch ${form.planRenewalSilent ? "is-on" : ""}`} aria-pressed={form.planRenewalSilent} onClick={() => change("planRenewalSilent", !form.planRenewalSilent)}><i /></button></label></fieldset><fieldset className="admin-form__full admin-permissions"><legend>Comandos e BotInterage</legend><label className="admin-toggle-row"><span>Comando !play</span><button type="button" className={`admin-switch ${form.allowPlay ? "is-on" : ""}`} aria-pressed={form.allowPlay} onClick={() => change("allowPlay", !form.allowPlay)}><i /></button></label><label className="admin-toggle-row"><span>Comando !ban</span><button type="button" className={`admin-switch ${form.allowBan ? "is-on" : ""}`} aria-pressed={form.allowBan} onClick={() => change("allowBan", !form.allowBan)}><i /></button></label><label className="admin-toggle-row"><span>Antilinks</span><button type="button" className={`admin-switch ${form.allowLinks ? "is-on" : ""}`} aria-pressed={form.allowLinks} onClick={() => change("allowLinks", !form.allowLinks)}><i /></button></label><label>Provedor<select value={form.aiProvider} onChange={(event) => change("aiProvider", event.currentTarget.value)}><option value="groq">Groq</option><option value="openai">OpenAI</option><option value="chatgpt_system">ChatGPT do sistema</option></select></label><label>Modelo<input value={form.aiModel} onChange={(event) => change("aiModel", event.currentTarget.value)} /></label><label className="admin-form__full">Prompt do bot<textarea rows={4} value={form.aiPrompt} onChange={(event) => change("aiPrompt", event.currentTarget.value)} placeholder="Instruções para o robô responder neste grupo" /></label><label className="admin-form__full">Mensagem de boas-vindas<textarea rows={3} value={form.welcomeText} onChange={(event) => change("welcomeText", event.currentTarget.value)} placeholder="Olá {{pushName}}, seja bem-vindo!" /></label></fieldset><fieldset className="admin-form__full admin-permissions"><legend>Transferência de gestão (opcional)</legend><label>ID do novo responsável<input inputMode="numeric" value={form.transferUserId} onChange={(event) => change("transferUserId", event.currentTarget.value)} placeholder="ID do usuário" /></label><label>ID da instância de destino<input inputMode="numeric" value={form.transferInstanceId} onChange={(event) => change("transferInstanceId", event.currentTarget.value)} placeholder="Opcional" /></label><p className="admin-form-help">A transferência é aplicada junto com o salvamento e não remove o grupo.</p></fieldset></form></AdminModal>;
}

export function AdminGroupsWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [groups, setGroups] = useState<JsonRecord[]>([]); const [query, setQuery] = useState(""); const [hasMore, setHasMore] = useState(false); const [loading, setLoading] = useState(true); const [editor, setEditor] = useState<JsonRecord | null>(null); const [remove, setRemove] = useState<JsonRecord | null>(null); const pageRef = useRef(0);
  const load = useCallback(async (reset = true) => { setLoading(true); const nextPage = reset ? 1 : pageRef.current + 1; try { const response = await adminApi.groups({ query: query.trim() || undefined, page: nextPage, pageSize: 30 }); const list = asList(response, ["groups", "items"]); pageRef.current = nextPage; setGroups((current) => { const merged = reset ? list : [...current, ...list]; setHasMore(bool(response.hasMore) || asNumber(response.total) > merged.length); return merged; }); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast, query]);
  useEffect(() => { const timer = window.setTimeout(() => void load(true), 180); return () => window.clearTimeout(timer); }, [load]);
  const openEditor = async (group: JsonRecord) => { try { const response = await adminApi.group(idOf(group)); setEditor((response.summary || response.group || group) as JsonRecord); } catch (error) { onToast(errText(error), false); } };
  const deleteGroup = async () => { if (!remove) return; try { await adminApi.group(idOf(remove), undefined, "DELETE"); onToast("Grupo removido.", true); setRemove(null); void load(true); } catch (error) { onToast(errText(error), false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load(true)} refreshing={loading} /><div className="admin-toolbar"><AdminSearchBar value={query} onChange={setQuery} placeholder="Pesquisar grupo, usuário ou JID" /><span className="admin-toolbar__count">{groups.length} carregados</span></div>{loading && groups.length === 0 ? <AdvancedLoading label="Carregando grupos…" /> : groups.length === 0 ? <AdvancedEmpty icon={Users} title="Nenhum grupo encontrado" message="Os grupos vinculados aos usuários aparecerão aqui." /> : <><div className="admin-record-list">{groups.map((group) => <AdminRecordCard key={idOf(group)} record={{ ...group, title: titleOf(group, `Grupo #${idOf(group)}`), email: group.ownerEmail || group.userEmail, status: bool(group.active ?? group.isActive, true) ? "Ativo" : "Inativo" }} extra={<small>{asText(group.ownerName || group.userName, "Usuário")} · {asNumber(group.memberCount || group.participantsCount)} membros · {asText(group.remoteId || group.jid, "JID não informado")}</small>} actions={<details className="admin-more"><summary aria-label="Ações do grupo"><MoreVertical size={17} /></summary><div className="admin-more__menu"><button type="button" onClick={() => void openEditor(group)}><Pencil size={15} />Gerenciar grupo</button><button type="button" onClick={() => navigateAdmin("instances")}><Server size={15} />Abrir perfil</button><button type="button" className="is-danger" onClick={() => setRemove(group)}><Trash2 size={15} />Excluir grupo</button></div></details>} />)}</div>{hasMore ? <button type="button" className="admin-button admin-button--ghost" onClick={() => void load(false)} disabled={loading}>{loading ? "Carregando…" : "Carregar mais"}</button> : null}</>}{editor ? <GroupEditor item={editor} onClose={() => setEditor(null)} onSaved={() => void load(true)} onToast={onToast} /> : null}{remove ? <AdvancedConfirm title="Excluir grupo?" message={`O grupo ${titleOf(remove)} e suas configurações serão removidos definitivamente.`} onCancel={() => setRemove(null)} onConfirm={() => void deleteGroup()} /> : null}</div>;
}

type AffiliateDraft = { enabled: boolean; appId: string; clientSecret: string; appToken: string; authEndpoint: string; tokenEndpoint: string; redirectUri: string; scopeText: string; extractorCookieText: string };
const affiliateDraft = (item?: JsonRecord | null): AffiliateDraft => ({ enabled: bool(item?.enabled), appId: asText(item?.appId), clientSecret: "", appToken: "", authEndpoint: asText(item?.authEndpoint), tokenEndpoint: asText(item?.tokenEndpoint), redirectUri: asText(item?.redirectUri), scopeText: asText(item?.scopeText), extractorCookieText: "" });

function AffiliateEditor({ provider, item, onClose, onSaved, onToast }: { provider: JsonRecord; item: JsonRecord; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [form, setForm] = useState(() => affiliateDraft(item)); const [saving, setSaving] = useState(false); const change = <K extends keyof AffiliateDraft>(key: K, value: AffiliateDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const importCookie = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.currentTarget.files?.[0]; event.currentTarget.value = ""; if (!file) return; try { change("extractorCookieText", await file.text()); onToast(`Cookie ${file.name} carregado. Salve para aplicar.`, true); } catch (error) { onToast(errText(error), false); } };
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.appId.trim() && !form.clientSecret.trim() && !form.appToken.trim() && !form.authEndpoint.trim()) { onToast("Informe ao menos uma credencial ou endpoint do provedor.", false); return; } setSaving(true); try { const payload: JsonRecord = { enabled: form.enabled, appId: form.appId.trim(), authEndpoint: form.authEndpoint.trim(), tokenEndpoint: form.tokenEndpoint.trim(), redirectUri: form.redirectUri.trim(), scopeText: form.scopeText.trim(), ...(form.clientSecret.trim() ? { clientSecret: form.clientSecret.trim() } : {}), ...(form.appToken.trim() ? { appToken: form.appToken.trim() } : {}), ...(form.extractorCookieText.trim() ? { extractorCookieText: form.extractorCookieText.trim() } : {}) }; await adminApi.affiliateProvider(asText(provider.provider), payload); onToast("Provedor de afiliados atualizado.", true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const authUrl = asText(item.authEndpoint);
  return <AdminModal title={`Configurar ${asText(provider.name || provider.label || provider.provider)}`} subtitle="Credenciais separadas por plataforma, com OAuth e cookies protegidos." onClose={onClose} wide footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="affiliate-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar provedor"}</button></>}><form id="affiliate-form" className="admin-form admin-form--grid" onSubmit={submit}><label className="admin-toggle-row admin-form__full"><span>Provedor habilitado</span><button type="button" className={`admin-switch ${form.enabled ? "is-on" : ""}`} aria-pressed={form.enabled} onClick={() => change("enabled", !form.enabled)}><i /></button></label><label>App ID / Client ID<input value={form.appId} onChange={(event) => change("appId", event.currentTarget.value)} autoFocus /></label><label>Client Secret <small>(vazio mantém)</small><input type="password" value={form.clientSecret} onChange={(event) => change("clientSecret", event.currentTarget.value)} autoComplete="new-password" /></label><label>App token <small>(vazio mantém)</small><input type="password" value={form.appToken} onChange={(event) => change("appToken", event.currentTarget.value)} autoComplete="new-password" /></label><label>Escopos OAuth<input value={form.scopeText} onChange={(event) => change("scopeText", event.currentTarget.value)} placeholder="read_products,write_links" /></label><label className="admin-form__full">Endpoint de autorização<input type="url" value={form.authEndpoint} onChange={(event) => change("authEndpoint", event.currentTarget.value)} /></label><label>Endpoint de token<input type="url" value={form.tokenEndpoint} onChange={(event) => change("tokenEndpoint", event.currentTarget.value)} /></label><label>Redirect URI<input type="url" value={form.redirectUri} onChange={(event) => change("redirectUri", event.currentTarget.value)} /></label><label className="admin-form__full">Cookie do extrator <small>(vazio mantém)</small><textarea rows={4} value={form.extractorCookieText} onChange={(event) => change("extractorCookieText", event.currentTarget.value)} placeholder="Cole o cookie completo da sessão" /></label><label className="admin-form__full admin-file-field">Importar cookie de arquivo<input type="file" accept=".txt,.json" onChange={importCookie} /></label>{authUrl ? <p className="admin-form-help admin-form__full"><ExternalLink size={15} /><a href={authUrl} target="_blank" rel="noreferrer">Abrir autorização OAuth</a></p> : null}</form></AdminModal>;
}

export function AdminAffiliatesWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [providers, setProviders] = useState<JsonRecord[]>([]); const [selected, setSelected] = useState<JsonRecord | null>(null); const [loading, setLoading] = useState(true);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.affiliateProviders(); const list = asList(response, ["providers"]); setProviders(list); setSelected((current) => current ? list.find((item) => asText(item.provider) === asText(current.provider)) || current : list[0] || null); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<button type="button" className="admin-button admin-button--ghost" onClick={() => void load()}><RefreshCw size={16} />Atualizar lista</button>} />{loading ? <AdvancedLoading label="Carregando provedores…" /> : providers.length === 0 ? <AdvancedEmpty icon={ExternalLink} title="Nenhum provedor disponível" message="A configuração de afiliados retornou uma lista vazia." /> : <div className="admin-two-column"><section className="admin-subpanel"><header><div><h2>Plataformas</h2><p>Selecione uma conta para configurar.</p></div><Link2 size={20} /></header><div className="admin-mini-list">{providers.map((provider) => <button type="button" className={`admin-mini-row admin-mini-row--button ${selected?.provider === provider.provider ? "is-selected" : ""}`} key={asText(provider.provider)} onClick={() => setSelected(provider)}><span className="admin-avatar">{asText(provider.provider, "A").slice(0, 1).toUpperCase()}</span><div><strong>{asText(provider.name || provider.label || provider.provider)}</strong><small>{provider.runtimeEnabled ? "Ativo em produção" : provider.implemented === false ? "Em breve" : provider.enabled ? "Configuração incompleta" : "Desativado"}</small></div><AdminStatusPill value={provider.runtimeEnabled ? "Ativo" : provider.implemented === false ? "Em breve" : provider.enabled ? "Pendente" : "Inativo"} /></button>)}</div></section><section className="admin-subpanel"><header><div><h2>{asText(selected?.name || selected?.label || selected?.provider, "Provedor")}</h2><p>OAuth, cookies e credenciais da plataforma.</p></div><Settings size={20} /></header>{selected ? <><dl className="admin-detail-list"><div><dt>Implementado</dt><dd>{bool(selected.implemented, true) ? "Sim" : "Em breve"}</dd></div><div><dt>Atualizado</dt><dd>{asDate(selected.updatedAt)}</dd></div><div><dt>OAuth</dt><dd>{asText(selected.redirectUri, "URI padrão")}</dd></div></dl><button type="button" className="admin-button admin-button--primary" onClick={() => setSelected({ ...selected, __editing: true })}><Pencil size={16} />Editar credenciais</button>{selected.__editing ? <AffiliateEditor provider={selected} item={selected} onClose={() => setSelected((current) => current ? { ...current, __editing: false } : null)} onSaved={() => void load()} onToast={onToast} /> : null}</> : <AdvancedEmpty title="Selecione uma plataforma" message="As credenciais serão exibidas somente após a seleção." />}</section></div>}</div>;
}

type SiteDraft = { siteName: string; logoUrl: string; description: string; seoTitle: string; seoDescription: string; ogImageUrl: string; officialGroupInviteLink: string; officialGroupId: string; officialGroupInstanceId: string };
const siteDraft = (item?: JsonRecord | null): SiteDraft => ({ siteName: asText(item?.siteName || item?.name), logoUrl: asText(item?.logoUrl), description: asText(item?.description), seoTitle: asText(item?.seoTitle), seoDescription: asText(item?.seoDescription), ogImageUrl: asText(item?.ogImageUrl), officialGroupInviteLink: asText(item?.officialGroupInviteLink), officialGroupId: asText(item?.officialGroupId), officialGroupInstanceId: asText(item?.officialGroupInstanceId) });

export function AdminSiteWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [form, setForm] = useState<SiteDraft>(() => siteDraft()); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [refreshingLink, setRefreshingLink] = useState(false);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.siteSettings(); const next = (response.config || response.settings || response) as JsonRecord; setForm(siteDraft(next)); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]); const change = <K extends keyof SiteDraft>(key: K, value: SiteDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.siteName.trim()) { onToast("Informe o nome do site.", false); return; } setSaving(true); try { const payload = new FormData(); Object.entries(form).forEach(([key, value]) => payload.append(key, value)); await adminApi.siteSettings(Object.fromEntries(payload.entries())); onToast("Configurações do site salvas.", true); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const refreshLink = async () => { setRefreshingLink(true); try { const response = await adminApi.officialGroupLink({ groupId: form.officialGroupId || undefined, instanceId: form.officialGroupInstanceId || undefined, reset: true }); setForm((current) => ({ ...current, officialGroupInviteLink: asText(response.inviteLink || (response.settings as JsonRecord | undefined)?.officialGroupInviteLink) })); onToast("Link oficial atualizado.", true); } catch (error) { onToast(errText(error), false); } finally { setRefreshingLink(false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<button type="submit" form="site-settings-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar"}</button>} />{loading ? <AdvancedLoading label="Carregando identidade do site…" /> : <section className="admin-info-card admin-info-card--wide admin-page-form"><div className="admin-info-card__head"><span className="admin-avatar"><Settings size={18} /></span><div><strong>Identidade, SEO e grupo oficial</strong><span>Configurações públicas aplicadas à landing page e aos compartilhamentos.</span></div></div><form id="site-settings-form" className="admin-form admin-form--grid" onSubmit={submit}><label>Nome do site<input value={form.siteName} onChange={(event) => change("siteName", event.currentTarget.value)} autoFocus /></label><label>Logo URL<input type="url" value={form.logoUrl} onChange={(event) => change("logoUrl", event.currentTarget.value)} placeholder="https://…" /></label><label className="admin-form__full">Descrição pública<textarea rows={3} value={form.description} onChange={(event) => change("description", event.currentTarget.value)} /></label><label>SEO title<input value={form.seoTitle} onChange={(event) => change("seoTitle", event.currentTarget.value)} /></label><label>Imagem Open Graph<input type="url" value={form.ogImageUrl} onChange={(event) => change("ogImageUrl", event.currentTarget.value)} /></label><label className="admin-form__full">SEO description<textarea rows={3} value={form.seoDescription} onChange={(event) => change("seoDescription", event.currentTarget.value)} /></label><fieldset className="admin-form__full admin-permissions"><legend>Grupo oficial</legend><label>Link atual<input value={form.officialGroupInviteLink} onChange={(event) => change("officialGroupInviteLink", event.currentTarget.value)} /></label><label>ID do grupo<input value={form.officialGroupId} onChange={(event) => change("officialGroupId", event.currentTarget.value)} /></label><label>ID da instância<input value={form.officialGroupInstanceId} onChange={(event) => change("officialGroupInstanceId", event.currentTarget.value)} /></label><button type="button" className="admin-button admin-button--ghost" onClick={() => void refreshLink()} disabled={refreshingLink}><RefreshCw size={15} />{refreshingLink ? "Atualizando…" : "Redefinir link oficial"}</button></fieldset></form></section>}</div>;
}

type FirebaseDraft = { enabled: boolean; projectId: string; clientEmail: string; privateKey: string; apiKey: string; appId: string; messagingSenderId: string };
export function AdminFirebaseWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [form, setForm] = useState<FirebaseDraft>({ enabled: false, projectId: "", clientEmail: "", privateKey: "", apiKey: "", appId: "", messagingSenderId: "" }); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.firebaseSettings(); const next = (response.config || response.settings || response) as JsonRecord; setForm({ enabled: bool(next.enabled ?? next.isActive), projectId: asText(next.projectId), clientEmail: asText(next.clientEmail), privateKey: "", apiKey: "", appId: asText(next.appId), messagingSenderId: asText(next.messagingSenderId) }); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]); const change = <K extends keyof FirebaseDraft>(key: K, value: FirebaseDraft[K]) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.projectId.trim()) { onToast("Informe o Project ID do Firebase.", false); return; } setSaving(true); try { const payload = new FormData(); Object.entries(form).forEach(([key, value]) => payload.append(key, String(value))); await adminApi.firebaseSettings(Object.fromEntries(payload.entries())); onToast("Firebase atualizado.", true); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} />{loading ? <AdvancedLoading label="Carregando Firebase…" /> : <section className="admin-info-card admin-info-card--wide"><div className="admin-info-card__head"><span className="admin-avatar"><Activity size={18} /></span><div><strong>Firebase / Push notifications</strong><span>Credenciais usadas pelo aplicativo e notificações.</span></div><AdminStatusPill value={form.enabled ? "Ativo" : "Inativo"} /></div><form className="admin-form admin-form--grid" onSubmit={submit}><label className="admin-toggle-row admin-form__full"><span>Firebase habilitado</span><button type="button" className={`admin-switch ${form.enabled ? "is-on" : ""}`} aria-pressed={form.enabled} onClick={() => change("enabled", !form.enabled)}><i /></button></label><label>Project ID<input value={form.projectId} onChange={(event) => change("projectId", event.currentTarget.value)} autoFocus /></label><label>Client email<input type="email" value={form.clientEmail} onChange={(event) => change("clientEmail", event.currentTarget.value)} /></label><label>App ID<input value={form.appId} onChange={(event) => change("appId", event.currentTarget.value)} /></label><label>Messaging sender ID<input value={form.messagingSenderId} onChange={(event) => change("messagingSenderId", event.currentTarget.value)} /></label><label>Nova API key <small>(vazio mantém)</small><input type="password" value={form.apiKey} onChange={(event) => change("apiKey", event.currentTarget.value)} autoComplete="new-password" /></label><label className="admin-form__full">Nova private key <small>(vazio mantém)</small><textarea rows={5} value={form.privateKey} onChange={(event) => change("privateKey", event.currentTarget.value)} /></label><div className="admin-form__full admin-form-actions"><button type="submit" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar Firebase"}</button></div></form></section>}</div>;
}

export function AdminMobileWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [settings, setSettings] = useState<JsonRecord>({}); const [artifacts, setArtifacts] = useState<JsonRecord>({}); const [signing, setSigning] = useState<JsonRecord>({}); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [apk, setApk] = useState<File | null>(null); const [keystore, setKeystore] = useState<File | null>(null); const [alias, setAlias] = useState(""); const [keyPassword, setKeyPassword] = useState(""); const [storePassword, setStorePassword] = useState("");
  const load = useCallback(async () => { setLoading(true); try { const [mobile, files, key] = await Promise.all([adminApi.mobileSettings(), adminApi.mobileArtifacts(), adminApi.mobileSigning()]); setSettings((mobile.config || mobile.settings || mobile) as JsonRecord); setArtifacts((files.manifest || files) as JsonRecord); setSigning(key as JsonRecord); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  const saveSettings = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSaving(true); try { const form = new FormData(event.currentTarget); const payload: JsonRecord = {}; form.forEach((value, key) => { payload[key] = String(value); }); await adminApi.mobileSettings(payload); onToast("Configurações do aplicativo salvas.", true); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const saveArtifact = async () => { if (!apk) { onToast("Selecione um APK para enviar.", false); return; } setSaving(true); try { const form = new FormData(); form.append("androidFile", apk); form.append("androidMode", "file"); await adminApi.mobileArtifacts(form); onToast("APK publicado para atualização.", true); setApk(null); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const saveSigning = async (event: FormEvent) => { event.preventDefault(); if (!keystore || !alias || !keyPassword || !storePassword) { onToast("Informe arquivo, alias e senhas do keystore.", false); return; } setSaving(true); try { const form = new FormData(); form.append("keystore", keystore); form.append("keyAlias", alias); form.append("keyPassword", keyPassword); form.append("storePassword", storePassword); await adminApi.mobileSigning(form, "PUT"); onToast("Keystore Android salvo.", true); setKeystore(null); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} />{loading ? <AdvancedLoading label="Carregando configuração do aplicativo…" /> : <div className="admin-two-column"><section className="admin-subpanel"><header><div><h2>Versão e distribuição</h2><p>Controle a atualização do Android e links das plataformas.</p></div><Smartphone size={20} /></header><form className="admin-form" onSubmit={saveSettings}><label>Versão exibida<input name="versionName" defaultValue={asText(settings.versionName)} /></label><label>Version code<input name="versionCode" type="number" min="1" defaultValue={asText(settings.versionCode, "1")} /></label><label>Versão mínima suportada<input name="minSupportedVersion" defaultValue={asText(settings.minSupportedVersion)} /></label><label>URL de atualização<input name="updateUrl" type="url" defaultValue={asText(settings.updateUrl)} /></label><label>Detalhes da versão<textarea name="releaseNotes" rows={4} defaultValue={asText(settings.releaseNotes)} /></label><button type="submit" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar versão"}</button></form><hr /><label className="admin-file-field">APK Android<input type="file" accept=".apk" onChange={(event) => setApk(event.currentTarget.files?.[0] || null)} /></label><button type="button" className="admin-button admin-button--ghost" onClick={() => void saveArtifact()} disabled={saving || !apk}><Upload size={15} />Publicar APK</button><div className="admin-mini-list">{artifacts.android ? <div className="admin-mini-row"><FileDown size={17} /><div><strong>{asText((artifacts.android as JsonRecord).fileName, "android-app.apk")}</strong><small>{asText((artifacts.android as JsonRecord).url)} · {asDate((artifacts.android as JsonRecord).updatedAt)}</small></div></div> : <small>Nenhum APK publicado.</small>}</div></section><section className="admin-subpanel"><header><div><h2>Assinatura Android</h2><p>Keystore protegido para builds assinados.</p></div><ShieldCheck size={20} /></header><AdminStatusPill value={signing.hasKeystore ? "Configurado" : "Pendente"} /><form className="admin-form" onSubmit={saveSigning}><label>Arquivo .jks/.keystore<input type="file" accept=".jks,.keystore,.p12" onChange={(event) => setKeystore(event.currentTarget.files?.[0] || null)} /></label><label>Alias<input value={alias} onChange={(event) => setAlias(event.currentTarget.value)} /></label><label>Senha do alias<input type="password" value={keyPassword} onChange={(event) => setKeyPassword(event.currentTarget.value)} autoComplete="new-password" /></label><label>Senha do keystore<input type="password" value={storePassword} onChange={(event) => setStorePassword(event.currentTarget.value)} autoComplete="new-password" /></label><button type="submit" className="admin-button admin-button--primary" disabled={saving}><ShieldCheck size={15} />Salvar keystore</button></form><a className="admin-button admin-button--ghost" href="/api/admin/mobile/signing?download=1" target="_blank" rel="noreferrer"><FileDown size={15} />Baixar keystore</a></section></div>}</div>;
}

type NotificationTab = "billing" | "smtp" | "templates" | "guard" | "broadcast";
export function AdminNotificationsWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [tab, setTab] = useState<NotificationTab>("billing"); const [billing, setBilling] = useState<JsonRecord>({}); const [smtp, setSmtp] = useState<JsonRecord>({}); const [guard, setGuard] = useState<JsonRecord>({}); const [templates, setTemplates] = useState<JsonRecord[]>([]); const [template, setTemplate] = useState<JsonRecord | null>(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [broadcast, setBroadcast] = useState({ subject: "", message: "", target: "all", email: "" });
  const load = useCallback(async () => { setLoading(true); try { const [billingResponse, smtpResponse, guardResponse, templateResponse] = await Promise.all([adminApi.billingNotifications(), adminApi.smtpSettings(), adminApi.planGuard(), adminApi.notificationTemplates()]); setBilling((billingResponse.settings || billingResponse) as JsonRecord); setSmtp((smtpResponse.settings || smtpResponse) as JsonRecord); setGuard((guardResponse.settings || guardResponse) as JsonRecord); setTemplates(asList(templateResponse, ["templates"])); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  const saveObject = async (event: FormEvent<HTMLFormElement>, kind: NotificationTab) => { event.preventDefault(); setSaving(true); try { const form = event.currentTarget; const data = new FormData(form); const payload: JsonRecord = {}; data.forEach((value, key) => { payload[key] = typeof value === "string" && (value === "true" || value === "false") ? value === "true" : String(value); }); form.querySelectorAll<HTMLInputElement>('input[type="checkbox"][name]').forEach((input) => { payload[input.name] = input.checked; }); if (kind === "billing") { await adminApi.billingNotifications(payload); } else if (kind === "smtp") { payload.port = Number(payload.port || 0); payload.secure = payload.secure === true; await adminApi.smtpSettings(payload); } else { const guardData = new FormData(); Object.entries(payload).forEach(([key, value]) => guardData.append(key, String(value))); await adminApi.planGuard(guardData); } onToast("Configuração salva.", true); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const saveTemplate = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!template) return; setSaving(true); try { const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()); await adminApi.notificationTemplate(asText(template.key || template.slug), payload as JsonRecord); onToast("Modelo de e-mail salvo.", true); setTemplate(null); void load(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const sendBroadcast = async (event: FormEvent) => { event.preventDefault(); if (!broadcast.subject.trim() || !broadcast.message.trim()) { onToast("Informe assunto e mensagem.", false); return; } setSaving(true); try { await adminApi.notificationBroadcast(broadcast); onToast("Notificação enviada.", true); setBroadcast({ subject: "", message: "", target: "all", email: "" }); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  const tabButton = (id: NotificationTab, label: string) => <button type="button" className={tab === id ? "is-active" : ""} onClick={() => setTab(id)}>{label}</button>;
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} /><div className="admin-segmented" role="tablist" aria-label="Notificações">{tabButton("billing", "Cobranças")}{tabButton("smtp", "SMTP")}{tabButton("templates", "Modelos de e-mail")}{tabButton("guard", "Bloqueio por vencimento")}{tabButton("broadcast", "Enviar aviso")}</div>{loading ? <AdvancedLoading label="Carregando notificações…" /> : tab === "templates" ? <section className="admin-subpanel"><header><div><h2>Modelos de e-mail</h2><p>Edite textos usados por senha, cobrança e verificações.</p></div><FileText size={20} /></header>{templates.length === 0 ? <AdvancedEmpty icon={FileText} title="Nenhum modelo cadastrado" message="Os modelos padrão aparecerão após a configuração." /> : <div className="admin-record-list">{templates.map((item) => <AdminRecordCard key={idOf(item) || asText(item.key)} record={{ ...item, title: titleOf(item, asText(item.key, "Modelo")), email: item.subject, status: "Configurado" }} extra={<small>{asText(item.description, "Modelo de notificação")} · atualizado {asDate(item.updatedAt)}</small>} actions={<button type="button" className="admin-icon-button" title="Editar" onClick={() => setTemplate(item)}><Pencil size={16} /></button>} />)}</div>}{template ? <AdminModal title={`Editar ${titleOf(template, "modelo")}`} subtitle="HTML e textos enviados aos usuários." onClose={() => setTemplate(null)} footer={<><button type="button" className="admin-button admin-button--ghost" onClick={() => setTemplate(null)}>Cancelar</button><button type="submit" form="template-form" className="admin-button admin-button--primary" disabled={saving}>Salvar modelo</button></>}><form id="template-form" className="admin-form" onSubmit={saveTemplate}><label>Assunto<input name="subject" defaultValue={asText(template.subject)} required /></label><label>Título<input name="heading" defaultValue={asText(template.heading)} /></label><label>Corpo HTML<textarea name="bodyHtml" rows={9} defaultValue={asText(template.bodyHtml || template.body)} required /></label><label>Texto do botão<input name="ctaLabel" defaultValue={asText(template.ctaLabel)} /></label><label>URL do botão<input name="ctaUrl" type="url" defaultValue={asText(template.ctaUrl)} /></label><label>Rodapé<input name="footerText" defaultValue={asText(template.footerText)} /></label></form></AdminModal> : null}</section> : tab === "broadcast" ? <section className="admin-info-card admin-info-card--wide"><div className="admin-info-card__head"><span className="admin-avatar"><Upload size={18} /></span><div><strong>Enviar notificação</strong><span>Entrega em tempo real e por e-mail aos usuários ativos.</span></div></div><form className="admin-form" onSubmit={sendBroadcast}><label>Assunto<input value={broadcast.subject} onChange={(event) => setBroadcast((current) => ({ ...current, subject: event.currentTarget.value }))} required /></label><label>Mensagem<textarea rows={7} value={broadcast.message} onChange={(event) => setBroadcast((current) => ({ ...current, message: event.currentTarget.value }))} required /></label><label>Destinatários<select value={broadcast.target} onChange={(event) => setBroadcast((current) => ({ ...current, target: event.currentTarget.value }))}><option value="all">Todos os usuários ativos</option><option value="email">Um usuário por e-mail</option></select></label>{broadcast.target === "email" ? <label>E-mail<input type="email" value={broadcast.email} onChange={(event) => setBroadcast((current) => ({ ...current, email: event.currentTarget.value }))} required /></label> : null}<button type="submit" className="admin-button admin-button--primary" disabled={saving}><Upload size={15} />Enviar aviso</button></form></section> : <section className="admin-info-card admin-info-card--wide"><div className="admin-info-card__head"><span className="admin-avatar"><Settings size={18} /></span><div><strong>{tab === "billing" ? "Notificações de cobrança" : tab === "smtp" ? "Servidor SMTP" : "Bloqueio por vencimento"}</strong><span>Configurações sincronizadas com o painel Flutter.</span></div></div><form className="admin-form admin-form--grid" onSubmit={(event) => void saveObject(event, tab)}>{Object.entries(tab === "billing" ? billing : tab === "smtp" ? smtp : guard).filter(([key, value]) => !/(secret|password|token|privateKey)/i.test(key) && typeof value !== "object").slice(0, 30).map(([key, value]) => <label key={key}>{key}<input name={key} type={typeof value === "boolean" ? "checkbox" : key.toLowerCase().includes("email") ? "email" : "text"} defaultValue={typeof value === "boolean" ? undefined : String(value ?? "")} defaultChecked={typeof value === "boolean" ? value : undefined} /></label>)}<p className="admin-form-help"><ShieldCheck size={15} />Campos sensíveis continuam protegidos pelo servidor.</p><button type="submit" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar configuração"}</button></form></section>}</div>;
}

export function AdminUsefulLinksWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [links, setLinks] = useState<JsonRecord[]>([]); const [banners, setBanners] = useState<JsonRecord[]>([]); const [loading, setLoading] = useState(true); const [editor, setEditor] = useState<{ kind: "link" | "banner"; item: JsonRecord | null } | null>(null); const [remove, setRemove] = useState<{ kind: "link" | "banner"; item: JsonRecord } | null>(null);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.usefulLinks(); setLinks(asList(response.links)); setBanners(asList(response.banners)); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  const removeItem = async () => { if (!remove) return; try { const id = idOf(remove.item); if (remove.kind === "link") await adminApi.usefulLink(id, undefined, "DELETE"); else await adminApi.usefulBanner(id, undefined, "DELETE"); onToast("Item removido.", true); setRemove(null); void load(); } catch (error) { onToast(errText(error), false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<><button type="button" className="admin-button admin-button--ghost" onClick={() => setEditor({ kind: "banner", item: null })}><Image size={16} />Novo banner</button><button type="button" className="admin-button admin-button--primary" onClick={() => setEditor({ kind: "link", item: null })}><Plus size={16} />Novo link</button></>} />{loading ? <AdvancedLoading label="Carregando links úteis…" /> : <div className="admin-two-column"><section className="admin-subpanel"><header><div><h2>Links úteis</h2><p>Atalhos mostrados no painel e na landing.</p></div><Link2 size={20} /></header>{links.length === 0 ? <AdvancedEmpty icon={Link2} title="Nenhum link cadastrado" message="Adicione um atalho oficial." /> : <div className="admin-record-list">{links.map((item) => <AdminRecordCard key={idOf(item)} record={{ ...item, title: titleOf(item), email: item.url, status: bool(item.isActive, true) ? "Ativo" : "Inativo" }} extra={<small>{asText(item.buttonLabel)} · ordem {asNumber(item.order)}</small>} actions={<><button type="button" className="admin-icon-button" onClick={() => setEditor({ kind: "link", item })} aria-label="Editar"><Pencil size={15} /></button><button type="button" className="admin-icon-button" onClick={() => setRemove({ kind: "link", item })} aria-label="Excluir"><Trash2 size={15} /></button></>} />)}</div>}</section><section className="admin-subpanel"><header><div><h2>Banners</h2><p>Imagens e GIFs exibidos nos destaques.</p></div><Image size={20} /></header>{banners.length === 0 ? <AdvancedEmpty icon={Image} title="Nenhum banner cadastrado" message="Envie uma imagem para criar um destaque." /> : <div className="admin-record-list">{banners.map((item) => <AdminRecordCard key={idOf(item)} record={{ ...item, title: titleOf(item), email: item.mediaUrl || item.url, status: bool(item.isActive, true) ? "Ativo" : "Inativo" }} extra={<small>{asText(item.subtitle)} · ordem {asNumber(item.order)}</small>} actions={<><button type="button" className="admin-icon-button" onClick={() => setEditor({ kind: "banner", item })} aria-label="Editar"><Pencil size={15} /></button><button type="button" className="admin-icon-button" onClick={() => setRemove({ kind: "banner", item })} aria-label="Excluir"><Trash2 size={15} /></button></>} />)}</div>}</section></div>}{editor ? <UsefulItemEditor kind={editor.kind} item={editor.item} onClose={() => setEditor(null)} onSaved={() => void load()} onToast={onToast} /> : null}{remove ? <AdvancedConfirm title={`Excluir ${remove.kind === "link" ? "link" : "banner"}?`} message={`O item ${titleOf(remove.item)} será removido definitivamente.`} onCancel={() => setRemove(null)} onConfirm={() => void removeItem()} /> : null}</div>;
}

function UsefulItemEditor({ kind, item, onClose, onSaved, onToast }: { kind: "link" | "banner"; item: JsonRecord | null; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [saving, setSaving] = useState(false); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); form.querySelectorAll<HTMLInputElement>('input[type="checkbox"][name]').forEach((input) => data.set(input.name, String(input.checked))); setSaving(true); try { if (kind === "link") await adminApi.usefulLink(item ? idOf(item) : "", data, item ? "PUT" : "POST"); else await adminApi.usefulBanner(item ? idOf(item) : "", data, item ? "PUT" : "POST"); onToast(`${kind === "link" ? "Link" : "Banner"} salvo.`, true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <AdminModal title={`${item ? "Editar" : "Novo"} ${kind === "link" ? "link útil" : "banner"}`} subtitle="As alterações ficam disponíveis imediatamente." onClose={onClose} footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="useful-item-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar"}</button></>}><form id="useful-item-form" className="admin-form admin-form--grid" onSubmit={submit}><label>Título<input name="title" defaultValue={asText(item?.title)} autoFocus required /></label>{kind === "link" ? <><label>URL<input name="url" type="url" defaultValue={asText(item?.url)} required /></label><label>Texto do botão<input name="buttonLabel" defaultValue={asText(item?.buttonLabel, "Abrir")} required /></label><label>Ícone<input name="icon" defaultValue={asText(item?.icon)} placeholder="link" /></label><label className="admin-form__full">Descrição<textarea name="description" rows={3} defaultValue={asText(item?.description)} /></label><label>Ordem<input name="order" type="number" defaultValue={asText(item?.order, "0")} /></label><label className="admin-toggle-row"><span>Ativo</span><input name="isActive" type="checkbox" defaultChecked={bool(item?.isActive, true)} /></label><label className="admin-form__full admin-file-field">Imagem opcional<input name="image" type="file" accept="image/*" /></label></> : <><label>Subtítulo<input name="subtitle" defaultValue={asText(item?.subtitle)} /></label><label>URL do destaque<input name="linkUrl" type="url" defaultValue={asText(item?.linkUrl)} /></label><label>Ordem<input name="order" type="number" defaultValue={asText(item?.order, "0")} /></label><label className="admin-toggle-row"><span>Ativo</span><input name="isActive" type="checkbox" defaultChecked={bool(item?.isActive, true)} /></label><label className="admin-form__full admin-file-field">Imagem ou GIF<input name="media" type="file" accept="image/*,.gif" required={!item} /></label></>}</form></AdminModal>;
}

export function AdminTutorialsWorkspace({ nav, onToast }: { nav: AdminNavItem; onToast: Toast }) {
  const [tutorials, setTutorials] = useState<JsonRecord[]>([]); const [loading, setLoading] = useState(true); const [editor, setEditor] = useState<JsonRecord | null | undefined>(undefined); const [remove, setRemove] = useState<JsonRecord | null>(null);
  const load = useCallback(async () => { setLoading(true); try { const response = await adminApi.tutorials(); setTutorials(asList(response, ["tutorials"])); } catch (error) { onToast(errText(error), false); } finally { setLoading(false); } }, [onToast]); useEffect(() => { void load(); }, [load]);
  const deleteTutorial = async () => { if (!remove) return; try { await adminApi.tutorial(asText(remove.slug), undefined, "DELETE"); onToast("Tutorial removido.", true); setRemove(null); void load(); } catch (error) { onToast(errText(error), false); } };
  return <div className="admin-module"><AdminPanelHeader item={nav} onRefresh={() => void load()} refreshing={loading} actions={<button type="button" className="admin-button admin-button--primary" onClick={() => setEditor(null)}><Plus size={16} />Novo tutorial</button>} />{loading ? <AdvancedLoading label="Carregando tutoriais…" /> : tutorials.length === 0 ? <AdvancedEmpty icon={FileText} title="Nenhum tutorial cadastrado" message="Adicione materiais para orientar os usuários." action={<button type="button" className="admin-button admin-button--primary" onClick={() => setEditor(null)}><Plus size={16} />Criar tutorial</button>} /> : <div className="admin-record-list">{tutorials.map((item) => <AdminRecordCard key={asText(item.slug, idOf(item))} record={{ ...item, title: titleOf(item, asText(item.slug, "Tutorial")), email: item.description, status: "Publicado" }} extra={<small>/{asText(item.slug)} · atualizado {asDate(item.updatedAt)}</small>} actions={<><button type="button" className="admin-icon-button" onClick={() => setEditor(item)} aria-label="Editar"><Pencil size={15} /></button><button type="button" className="admin-icon-button" onClick={() => setRemove(item)} aria-label="Excluir"><Trash2 size={15} /></button></>} />)}</div>}{editor !== undefined ? <TutorialEditor item={editor} onClose={() => setEditor(undefined)} onSaved={() => void load()} onToast={onToast} /> : null}{remove ? <AdvancedConfirm title="Excluir tutorial?" message={`O tutorial ${titleOf(remove)} será removido definitivamente.`} onCancel={() => setRemove(null)} onConfirm={() => void deleteTutorial()} /> : null}</div>;
}

function TutorialEditor({ item, onClose, onSaved, onToast }: { item: JsonRecord | null; onClose: () => void; onSaved: () => void; onToast: Toast }) {
  const [saving, setSaving] = useState(false); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = event.currentTarget; const slugInput = form.elements.namedItem("slug") as HTMLInputElement | null; const slug = slugInput?.value.trim() || ""; if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/i.test(slug)) { onToast("Use um slug com letras, números e hífens.", false); return; } setSaving(true); try { const data = new FormData(form); await adminApi.tutorial(slug, data, "PUT"); onToast("Tutorial salvo.", true); onSaved(); onClose(); } catch (error) { onToast(errText(error), false); } finally { setSaving(false); } };
  return <AdminModal title={item ? "Editar tutorial" : "Novo tutorial"} subtitle="Materiais exibidos na área de ajuda do BotAdmin." onClose={onClose} wide footer={<><button type="button" className="admin-button admin-button--ghost" onClick={onClose}>Cancelar</button><button type="submit" form="tutorial-form" className="admin-button admin-button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar tutorial"}</button></>}><form id="tutorial-form" className="admin-form" onSubmit={submit}><label>Slug<input name="slug" defaultValue={asText(item?.slug)} readOnly={Boolean(item)} placeholder="como-conectar" required /></label><label>Título<input name="title" defaultValue={asText(item?.title)} autoFocus required /></label><label>Descrição<textarea name="description" rows={8} defaultValue={asText(item?.description)} required /></label><label>Tipo de mídia<select name="mediaType" defaultValue={asText(item?.mediaType, "image")}><option value="image">Imagem</option><option value="video">Vídeo</option></select></label><label className="admin-file-field">Mídia do tutorial<input type="file" name="media" accept="image/*,video/*" /></label><label className="admin-toggle-row"><span>Remover mídia existente</span><input name="removeMedia" type="checkbox" /></label></form></AdminModal>;
}
